/* A lens distortion model */
typedef enum {
    RANT_DISTORTION_MODEL_NONE = 0,  /* an ideal pinhole */
    RANT_DISTORTION_MODEL_BROWN_CONRADY = 1,
    RANT_DISTORTION_MODEL_FISHEYE = 2,
    RANT_DISTORTION_MODEL_RATIONAL = 3
} RantDistortionModel;

/* The pinhole model of a camera and its lens distortion */
typedef struct {
    uint32_t width;    /* [px] the resolution these values hold for */
    uint32_t height;   /* [px] */
    double fx;         /* [px] focal length along x */
    double fy;         /* [px] focal length along y */
    double cx;         /* [px] principal point x */
    double cy;         /* [px] principal point y */
    double coeffs[8];  /* OpenCV's order: k1 k2 p1 p2 k3, then k4 k5 k6 for Rational, or k1 to k4 for Fisheye, 0 past that */
    uint64_t model;    /* RantDistortionModel, the lens distortion model */
} RantCameraIntrinsics;

/* One reading of an inertial measurement unit, in its own frame
 * A covariance with -1 first means that value is not measured */
typedef struct {
    RantQuaternion orientation;
    RantCovariance3 orientation_covariance;          /* [rad^2] about x, y and z */
    RantDouble3 angular_velocity;                    /* [rad/s] about each axis */
    RantCovariance3 angular_velocity_covariance;     /* [rad^2/s^2] */
    RantDouble3 linear_acceleration;                 /* [m/s^2] gravity included */
    RantCovariance3 linear_acceleration_covariance;  /* [m^2/s^4] */
} RantImu;

/* What a range sensor measures with */
typedef enum {
    RANT_RANGE_KIND_UNKNOWN = 0,  /* unstated */
    RANT_RANGE_KIND_ULTRASOUND = 1,
    RANT_RANGE_KIND_INFRARED = 2,
    RANT_RANGE_KIND_LASER = 3,
    RANT_RANGE_KIND_RADAR = 4
} RantRangeKind;

/* One distance from a sensor with a single beam or cone along its +x */
typedef struct {
    double distance;       /* [m] +inf when nothing is in range */
    double min;            /* [m] the shortest distance it reads */
    double max;            /* [m] the longest distance it reads */
    double field_of_view;  /* [rad] the full angle of the cone */
    uint64_t kind;         /* RantRangeKind */
} RantRangeReading;

/* The quality of a satellite position fix */
typedef enum {
    RANT_GNSS_STATUS_NO_FIX = 0,        /* the position is not valid */
    RANT_GNSS_STATUS_FIX = 1,           /* satellites alone */
    RANT_GNSS_STATUS_DIFFERENTIAL = 2,  /* corrected by SBAS or DGPS */
    RANT_GNSS_STATUS_RTK_FLOAT = 3,     /* RTK, ambiguities not yet resolved */
    RANT_GNSS_STATUS_RTK_FIXED = 4      /* RTK, centimeter level */
} RantGnssStatus;

/* A position from satellite navigation */
typedef struct {
    RantGeoPoint position;
    RantCovariance3 covariance;  /* [m^2] east, north and up */
    uint64_t status;             /* RantGnssStatus */
} RantGnssFix;

/* The kind of number in a block of raw data, numbered as in PCL */
typedef enum {
    RANT_SCALAR_KIND_I8 = 1,
    RANT_SCALAR_KIND_U8 = 2,
    RANT_SCALAR_KIND_I16 = 3,
    RANT_SCALAR_KIND_U16 = 4,
    RANT_SCALAR_KIND_I32 = 5,
    RANT_SCALAR_KIND_U32 = 6,
    RANT_SCALAR_KIND_F32 = 7,
    RANT_SCALAR_KIND_F64 = 8,
    RANT_SCALAR_KIND_I64 = 9,
    RANT_SCALAR_KIND_U64 = 10
} RantScalarKind;

